def find_multisubword_doc(
    model_name: str, words_per_doc: list[list[str]], cache_root: str | None = None
) -> int:
    """Index of the document with the most multi-subword words (tokenizer only)."""
    import transformers
    from transformers import AutoTokenizer

    from src.embed_bert import resolve_model_path

    transformers.utils.logging.set_verbosity_error()
    tok = AutoTokenizer.from_pretrained(resolve_model_path(model_name, cache_root))
    best, best_n = 0, -1
    for i, words in enumerate(words_per_doc):
        enc = tok(words, is_split_into_words=True, truncation=True, padding=False)
        ids = enc.word_ids() if hasattr(enc, "word_ids") else enc["word_ids"]
        counts = {}
        for wid in ids:
            if wid is not None:
                counts[wid] = counts.get(wid, 0) + 1
        n_multi = sum(1 for c in counts.values() if c > 1)
        if n_multi > best_n:
            best, best_n = i, n_multi
    return best


